import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"TOTP 与 MFA","description":"","frontmatter":{"title":"TOTP 与 MFA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/totp-mfa.md","filePath":"cs/totp-mfa.md","lastUpdated":1789023840000}'),A={name:"cs/totp-mfa.md"};function E(T,a,c,m,_,f){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="totp-与-mfa" tabindex="-1">TOTP 与 MFA <a class="header-anchor" href="#totp-与-mfa" aria-label="Permalink to &quot;TOTP 与 MFA&quot;">​</a></h1><div class="epigraph"><p>TOTP 把共享种子和时钟窗收成六位数字。它防的是「只要口令」的重放，防不住实时钓鱼与种子备份泄漏。MFA 的强度取决于第二因素是否与第一因素一起被骗。</p><footer>—— RFC 6238；RFC 4226 HOTP；NIST SP 800-63B</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/webauthn-fido2">WebAuthn</a>给出抗钓鱼方向。缺口是<strong>仍占主导的第二因素</strong>：短信、TOTP、推送。本课钉 TOTP 合同与 MFA 的威胁模型，不写种子提取步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态口令泄漏后长期可用。TOTP：HMAC 种子 + 时间步。窗口过大则重放窗变宽；种子进截图与密码库同步则第二因素退化。短信 SS7 不在本课展开，只点名「电话号码不是认证器」。</p><h3 id="mfa-疲劳" tabindex="-1">MFA 疲劳 <a class="header-anchor" href="#mfa-疲劳" aria-label="Permalink to &quot;MFA 疲劳&quot;">​</a></h3><p>反复推送可能逼出一次同意。策略应是数字匹配或 WebAuthn，而不是无限推送。</p><p><span class="marginnote">RFC 6238。NIST 800-63B 限制短信。本课禁止生成伪造 TOTP 的操作指南。时钟来自先前漂移课的粗同步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写验证：允许 ±1 步、一次性使用、种子只在登记时显示。对照 WebAuthn：无共享种子。账户恢复仍是最弱环。</p>',12)),(e(),s(h,null,{default:o(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E5%85%B1%E4%BA%AB%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20HMAC%5B%22HMAC%20%E6%97%B6%E9%97%B4%E6%AD%A5%22%5D%0A%20%20HMAC%20--%3E%20CODE%5B%22%E7%9F%AD%E7%A0%81%22%5D%0A%20%20CODE%20--%3E%20WIN%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E7%AA%97%E9%AA%8C%22%5D%0A%20%20PHISH%5B%22%E5%AE%9E%E6%97%B6%E9%92%93%E9%B1%BC%22%5D%20-.-%3E%7C%22%E7%94%A8%E6%88%B7%E4%B8%80%E8%B5%B7%E8%BE%93%E5%85%A5%22%7C%20CODE%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>第二因素把「只要口令库」变成「还要第二通道」。实时中间人仍可转发短码。密码破解下一课回到第一因素：口令如何被离线猜。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写短信劫持。密码破解下一课：哈希、盐、慢哈希。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WebAuthn 抗钓鱼；TOTP 是共享种子短码。</li><li>窗、一次性、种子保管是合同。</li><li>实时转发与恢复流程可绕过 MFA。</li><li>下一课密码破解（防御视角）。</li><li>出处：RFC 6238；RFC 4226；NIST SP 800-63B。</li></ul>',8))])}const B=i(A,[["render",E]]);export{P as __pageData,B as default};
